# Build3D sample level
# Sector polygon vertices must be wound counter-clockwise as seen from above
# (x right, y "north"). A shared wall between two sectors must be the exact
# same segment listed in opposite directions by each sector, with `portal`
# pointing at the neighbor's id.
#
# SECTOR id floor ceil floorColor ceilColor light floorTex ceilTex
# WALL x1 y1 x2 y2 portal color [texId]      texId: 0=brick 1=panel 2=stripes, -1=flat

PLAYER 200 150 0 0 41

# 0: Main Hall
SECTOR 0 0 160 0x3a3a3a 0x1b1b26 1.0
WALL 0 0 400 0 -1 0x8a5a3c 0
WALL 400 0 400 300 1 0x777777 1
WALL 400 300 0 300 3 0x777777 1
WALL 0 300 0 0 8 0x777777 1
ENDSECTOR

# 1: Corridor to the tall room (lower ceiling than the hall -> visible step)
SECTOR 1 0 128 0x3a3a3a 0x24242e 1.0
WALL 400 0 600 0 -1 0x8a5a3c 0
WALL 600 0 600 300 2 0x777777 1
WALL 600 300 400 300 -1 0x8a5a3c 0
WALL 400 300 400 0 0 0x777777 1
ENDSECTOR

# 2: Tall pillared room
SECTOR 2 0 220 0x2e3a2e 0x14181f 1.0
WALL 600 0 900 0 -1 0x8a5a3c 0
WALL 900 0 900 300 -1 0x556b55 2
WALL 900 300 600 300 -1 0x8a5a3c 0
WALL 600 300 600 0 1 0x777777 1
ENDSECTOR

# 3: Stair unit 1 (0 -> 24)
SECTOR 3 24 160 0x454545 0x1b1b26 1.0
WALL 0 300 400 300 0 0x777777 1
WALL 400 300 400 340 -1 0x8a5a3c 0
WALL 400 340 0 340 4 0x777777 1
WALL 0 340 0 300 -1 0x8a5a3c 0
ENDSECTOR

# 4: Stair unit 2 (24 -> 48)
SECTOR 4 48 160 0x484848 0x1b1b26 1.0
WALL 0 340 400 340 3 0x777777 1
WALL 400 340 400 380 -1 0x8a5a3c 0
WALL 400 380 0 380 5 0x777777 1
WALL 0 380 0 340 -1 0x8a5a3c 0
ENDSECTOR

# 5: Stair unit 3 (48 -> 72)
SECTOR 5 72 160 0x4b4b4b 0x1b1b26 1.0
WALL 0 380 400 380 4 0x777777 1
WALL 400 380 400 420 -1 0x8a5a3c 0
WALL 400 420 0 420 6 0x777777 1
WALL 0 420 0 380 -1 0x8a5a3c 0
ENDSECTOR

# 6: Stair unit 4 (72 -> 96)
SECTOR 6 96 160 0x4e4e4e 0x1b1b26 1.0
WALL 0 420 400 420 5 0x777777 1
WALL 400 420 400 460 -1 0x8a5a3c 0
WALL 400 460 0 460 7 0x777777 1
WALL 0 460 0 420 -1 0x8a5a3c 0
ENDSECTOR

# 7: Landing / balcony overlooking the hall
SECTOR 7 96 220 0x55556a 0x101018 1.0
WALL 0 460 400 460 6 0x777777 1
WALL 400 460 400 700 -1 0x8a5a3c 0
WALL 400 700 0 700 -1 0x8a5a3c 0
WALL 0 700 0 460 -1 0x8a5a3c 0
ENDSECTOR

# 8: Sunken pit room (step down from the hall)
SECTOR 8 -20 150 0x201010 0x1b1b26 0.7
WALL -250 0 0 0 -1 0x8a5a3c 0
WALL 0 0 0 300 0 0x777777 1
WALL 0 300 -250 300 -1 0x8a5a3c 0
WALL -250 300 -250 0 -1 0x8a5a3c 0
ENDSECTOR

SPRITE 700 100 2 0 0x3388cc 1.0
SPRITE 800 200 2 0 0x3388cc 1.0
SPRITE 650 250 2 0 0x3388cc 1.0
SPRITE 200 600 7 0 0xffcc44 1.3
SPRITE -125 150 8 0 0xaa4444 1.0
